from lfx.custom.custom_component.component import Component
from lfx.io import DataFrameInput, Output
from lfx.schema.dataframe import DataFrame

import pandas as pd
import json
import re
import logging

logger = logging.getLogger(__name__)


class PdfPlumberToMarkdown(Component):
    """
    Downstream of PDFPlumberPageSelector.

    Converts the multi-row pdfplumber DataFrame (page_text / table /
    table_text rows) into a SINGLE-row Markdown document so the unified
    cleaner → BatchRun → LLM semantic-unit pipeline can process it
    identically to web and Office files.

    Rules:
      - record_type == "table_text"  -> IGNORED (the structured "table"
        row already carries the same content as a Markdown table).
      - record_type == "table"       -> rendered as a Markdown table.
      - record_type == "page_text"   -> heading (## if header_detected)
        or paragraph.
      - ALL document-level metadata columns are preserved on the output
        row (row-level extraction columns are dropped).

    Output: single-row DataFrame with 'markdown' + all doc metadata.
    """

    display_name = "PDF Plumber → Markdown"
    description = (
        "Converts the PageSelector pdfplumber DataFrame into a single "
        "Markdown document. Ignores table_text rows; keeps all "
        "document-level metadata."
    )

    inputs = [
        DataFrameInput(
            name="dataframe",
            display_name="PageSelector DataFrame",
            info="Multi-row DataFrame from PDFPlumberPageSelector.",
        ),
    ]

    outputs = [
        Output(
            name="result",
            display_name="Markdown DataFrame",
            method="process",
            type=DataFrame,
        )
    ]

    # Row-level / extraction columns that are NOT document metadata.
    # Everything else on the row is treated as document-level metadata
    # and carried through to the single output row.
    _ROW_LEVEL_COLS = {
        "record_type", "text", "page_number", "page_height",
        "page_element_index", "tbl_index", "tbl_metadata",
        "header_detected", "header_row_reference", "vertical_position",
        "dummy_record", "file_item_uuid", "output_row_number",
        "source_extraction", "routing_decision", "txt_structure_detected",
        "text_extracted", "source_name",
    }

    def process(self) -> DataFrame:
        try:
            df = self.dataframe

            if not isinstance(df, pd.DataFrame) or df.empty:
                return self._error_df("Empty or invalid input", None)

            # Drop dummy records
            if "dummy_record" in df.columns:
                real = df[df["dummy_record"] != True]
            else:
                real = df
            if real.empty:
                return self._error_df("Only dummy records in input", None)

            meta = self._doc_metadata(real)

            # Sort by page + element index for correct reading order
            sort_cols = [c for c in ("page_number", "page_element_index")
                         if c in real.columns]
            df_sorted = real.sort_values(sort_cols).reset_index(drop=True) \
                if sort_cols else real.reset_index(drop=True)

            markdown = self._build_markdown(df_sorted)

            if not markdown or not markdown.strip():
                return self._error_df("Empty Markdown output", meta)

            # Build single output row: all doc metadata + markdown
            row = dict(meta)
            row["source_type"] = row.get("source_type", "pdf")
            row["markdown"] = markdown
            row["error_reason"] = None

            n_pages = (df_sorted["page_number"].nunique()
                       if "page_number" in df_sorted.columns else "?")
            logger.info(
                f"[PDF→MD] {len(real)} rows → {len(markdown)} chars markdown, "
                f"{n_pages} pages, {len(meta)} metadata cols"
            )

            return DataFrame(pd.DataFrame([row]))

        except Exception as e:
            logger.error(f"[PDF→MD] Exception: {e}")
            return self._error_df(
                f"Exception: {str(e)}",
                meta if "meta" in dir() else None,
            )

    # ═════════════════════════════════════════════════════════
    # METADATA
    # ═════════════════════════════════════════════════════════

    def _doc_metadata(self, df: pd.DataFrame) -> dict:
        """Keep every column that is NOT a row-level extraction column."""
        first = df.iloc[0].to_dict()
        return {
            k: v for k, v in first.items()
            if k not in self._ROW_LEVEL_COLS
        }

    # ═════════════════════════════════════════════════════════
    # MARKDOWN BUILDER
    # ═════════════════════════════════════════════════════════

    def _build_markdown(self, df: pd.DataFrame) -> str:
        parts = []
        current_page = None

        for _, row in df.iterrows():
            record_type = str(row.get("record_type", ""))

            # ── IGNORE table_text rows entirely ──────────────
            if record_type == "table_text":
                continue

            page_num = row.get("page_number")
            text = str(row.get("text", "")).strip()
            if not text:
                continue

            # Page-break separator (skip before the first page)
            if page_num != current_page:
                if current_page is not None:
                    parts.append("\n---\n")
                current_page = page_num

            if record_type == "page_text":
                if str(row.get("header_detected")) == "yes":
                    heading = text if text.startswith("#") else f"## {text}"
                    parts.append(f"\n{heading}\n")
                else:
                    parts.append(f"\n{text}\n")

            elif record_type == "table":
                md_table = self._matrix_to_markdown_table(text)
                if md_table:
                    parts.append(f"\n{md_table}\n")
                else:
                    # not a JSON matrix → emit raw
                    parts.append(f"\n{text}\n")

            else:
                # any other record_type → keep its text
                parts.append(f"\n{text}\n")

        result = "\n".join(parts)
        result = re.sub(r'\n{3,}', '\n\n', result).strip()
        return result

    def _matrix_to_markdown_table(self, json_text: str) -> str:
        """Convert a JSON table matrix to a Markdown table."""
        try:
            matrix = json.loads(json_text)
        except (json.JSONDecodeError, TypeError):
            return ""
        if not matrix or not isinstance(matrix, list):
            return ""

        matrix = [
            r for r in matrix
            if isinstance(r, list) and any((str(c).strip() if c else "") for c in r)
        ]
        if not matrix:
            return ""

        max_cols = max(len(r) for r in matrix)
        norm = []
        for r in matrix:
            cells = [(str(c).strip().replace("\n", " ") if c else "") for c in r]
            cells += [""] * (max_cols - len(cells))
            norm.append(cells)

        lines = ["| " + " | ".join(norm[0]) + " |",
                 "| " + " | ".join(["---"] * max_cols) + " |"]
        for r in norm[1:]:
            lines.append("| " + " | ".join(r) + " |")
        return "\n".join(lines)

    # ═════════════════════════════════════════════════════════
    # ERROR HANDLING
    # ═════════════════════════════════════════════════════════

    def _error_df(self, message: str, meta: dict = None) -> DataFrame:
        logger.warning(f"[PDF→MD] {message}")
        row = dict(meta) if meta else {}
        row["markdown"] = None
        row["error_reason"] = message
        return DataFrame(pd.DataFrame([row]))

