from lfx.custom.custom_component.component import Component
from lfx.io import DataFrameInput, Output
from lfx.schema.dataframe import DataFrame

import pandas as pd
import os
import logging

logger = logging.getLogger(__name__)


class PdfMarkitdownExtractor(Component):
    """
    Branch A of the multi-strategy PDF flow.

    Reads a PDF saved by FastAPI and converts it to Markdown using
    markitdown (a non-pdfplumber engine). This is the lightweight
    candidate that the downstream LLM judge compares against the
    structured pdfplumber pipeline (Branches B+C via PageSelector).

    Input:  Single-row DataFrame from APIPipelineInput (file_path)
    Output: Single-row DataFrame with:
            - markdown:           Markdown text
            - extraction_method:  "markitdown"
            - error_reason:       null on success
    """

    display_name = "A) PDF → Markdown (markitdown)"
    description = (
        "Branch A extractor: converts a PDF to Markdown using markitdown "
        "(non-pdfplumber engine). Tagged extraction_method='markitdown' "
        "for the downstream LLM judge."
    )

    inputs = [
        DataFrameInput(
            name="dataframe",
            display_name="Input Metadata Row",
            info="Single-row DataFrame from APIPipelineInput with file_path.",
        ),
    ]

    outputs = [
        Output(
            name="result",
            display_name="Markdown DataFrame",
            method="process",
            type=DataFrame,
        )
    ]

    _METHOD = "markitdown"

    def process(self) -> DataFrame:
        try:
            df = self.dataframe

            if not isinstance(df, pd.DataFrame) or df.empty:
                return self._error_df("Empty or invalid input", None)

            meta = df.iloc[0].to_dict()
            file_path = meta.get("file_path")

            if not file_path:
                return self._error_df("No file_path in input", meta)

            if not os.path.exists(file_path):
                return self._error_df(f"File not found: {file_path}", meta)

            ext = os.path.splitext(file_path)[1].lower()
            if ext != ".pdf":
                return self._error_df(
                    f"Unsupported file type: {ext}. Expected: .pdf", meta
                )

            markdown_text = self._convert(file_path)

            if not markdown_text or not markdown_text.strip():
                return self._error_df("Empty Markdown output", meta)

            result_df = df.copy()
            result_df["markdown"] = markdown_text
            result_df["extraction_method"] = self._METHOD
            result_df["error_reason"] = None

            logger.info(
                f"[A:MARKITDOWN] file={os.path.basename(file_path)} "
                f"markdown={len(markdown_text)} chars"
            )

            return DataFrame(result_df)

        except Exception as e:
            logger.error(f"[A:MARKITDOWN] Exception: {e}")
            return self._error_df(
                f"Exception: {str(e)}",
                meta if "meta" in dir() else None,
            )

    def _convert(self, file_path: str) -> str:
        from markitdown import MarkItDown
        result = MarkItDown().convert(file_path)
        return result.text_content or ""

    def _error_df(self, message: str, meta: dict = None) -> DataFrame:
        logger.warning(f"[A:MARKITDOWN] {message}")
        row = dict(meta) if meta else {}
        row["markdown"] = None
        row["extraction_method"] = self._METHOD
        row["error_reason"] = message
        return DataFrame(pd.DataFrame([row]))
